1646.     pub open spec fn next_step(self, s: ClusterState, s_prime: ClusterState, step: Step) -> bool {
1647.         match step {
1648.             Step::APIServerStep(input) => self.api_server_next().forward(input)(s, s_prime),
1649.             Step::BuiltinControllersStep(input) => self.builtin_controllers_next().forward(input)(s, s_prime),
1650.             Step::ControllerStep(input) => self.controller_next().forward(input)(s, s_prime),
1651.             Step::ScheduleControllerReconcileStep(input) => self.schedule_controller_reconcile().forward(input)(s, s_prime),
1652.             Step::RestartControllerStep(input) => self.restart_controller().forward(input)(s, s_prime),
1653.             Step::DisableCrashStep(input) => self.disable_crash().forward(input)(s, s_prime),
1654.             Step::DropReqStep(input) => self.drop_req().forward(input)(s, s_prime),
1655.             Step::DisableReqDropStep => self.disable_req_drop().forward(())(s, s_prime),
1656.             Step::PodMonkeyStep(input) => self.pod_monkey_next().forward(input)(s, s_prime),
1657.             Step::DisablePodMonkeyStep => self.disable_pod_monkey().forward(())(s, s_prime),
1658.             Step::ExternalStep(input) => self.external_next().forward(input)(s, s_prime),
1659.             Step::StutterStep => self.stutter().forward(())(s, s_prime),
1660.         }
1661.     }
