1665.             let host_result = self.api_server().next_result(
1666.                 APIServerActionInput{ recv: input },
1667.                 s.api_server
1668.             );
1669.             let msg_ops = MessageOps {
1670.                 recv: input,
1671.                 send: host_result.get_Enabled_1().send,
1672.             };
1673.             let network_result = network().next_result(msg_ops, s.network);
1674. 
1675.             (host_result, network_result)
1676.         };
