1678.             precondition: |input: Option<Message>, s: ClusterState| {
1679.                 &&& received_msg_destined_for(input, HostId::APIServer)
1680.                 &&& result(input, s).0.is_Enabled()
1681.                 &&& result(input, s).1.is_Enabled()
