3152. pub uninterp spec fn deletion_timestamp() -> StringView;
3153. 
3154. pub open spec fn handle_delete_request(req: DeleteRequest, s: APIServerState) -> (APIServerState, DeleteResponse) {
3155.     if delete_request_admission_check(req, s) is Some {
3156.         // Deletion fails.
3157.         (s, DeleteResponse{res: Err(delete_request_admission_check(req, s)->0)})
3158.     } else {
3159.         // Deletion succeeds.
3160.         let obj = s.resources[req.key];
3161.         if obj.metadata.finalizers is Some && obj.metadata.finalizers->0.len() > 0 {
3162.             // With the finalizer(s) in the object, we cannot immediately delete it from the key-value store.
3163.             // Instead, we set the deletion timestamp of this object.
3164.             // If the object already has a deletion timestamp, then skip.
3165.             //
3166.             // NOTE: Having finalizer(s) is not the only reason that a deletion is postponed. Having a graceful
3167.             // period set in the deletion option is another reason. Currently we do not model the graceful period
3168.             // option so we don't model how the API server checks whether a deletion should be graceful.
3169.             // However, even without a graceful period option, deleting a Pod can still be graceful depending on its
3170.             // spec content (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/apis/core/types.go#L3256)
3171.             // because Pod implements CheckGracefulDelete (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/registry/core/pod/strategy.go#L168).
3172.             // This is irrelevant to application controllers that do not manage pods, and acceptable for verifying
3173.             // low-level built-in controllers because they are supposed to treat terminating pods as non-existing pods.
3174.             if obj.metadata.deletion_timestamp is Some {
3175.                 // A deletion timestamp is already set so no need to bother it.
3176.                 (s, DeleteResponse{res: Ok(())})
3177.             } else {
3178.                 let stamped_obj_with_new_rv = obj.with_deletion_timestamp(deletion_timestamp())
3179.                                                  .with_resource_version(s.resource_version_counter);
3180.                 (APIServerState {
3181.                     // Here we use req.key, instead of stamped_obj.object_ref(), to insert to the map.
3182.                     // This is intended because using stamped_obj.object_ref() will require us to use
3183.                     // the invariant each_object_in_etcd_is_well_formed a lot more frequently:
3184.                     // we need this invariant to convince Verus that the stamped_obj is well formed
3185.                     // so the key we use to insert to the map is the same as req.key.
3186.                     resources: s.resources.insert(req.key, stamped_obj_with_new_rv),
3187.                     resource_version_counter: s.resource_version_counter + 1,
3188.                     ..s
3189.                 }, DeleteResponse{res: Ok(())})
3190.             }
3191.         } else {
3192.             // The object can be immediately removed from the key-value store.
3193.             //
3194.             // NOTE: In some very corner case, the API server *seems* to first updates the object (to update its finalizers)
3195.             // and then deletes the object immediately, which makes the entire Delete operation not atomic.
3196.             // However, this only happens in the orphan or foreground deletion mode, so we do not model this
3197.             // seemingly non-atomic behavior for now.
3198.             // For more details, see how the API server updates the object in the middle of handling deletion requests:
3199.             // https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L1009
3200.             (APIServerState {
3201.                 resources: s.resources.remove(req.key),
3202.                 resource_version_counter: s.resource_version_counter + 1,
3203.                 ..s
3204.             }, DeleteResponse{res: Ok(())})
3205.         }
3206.     }
3207. }
