3216. pub open spec fn update_request_admission_check_helper(installed_types: InstalledTypes, name: StringView, namespace: StringView, obj: DynamicObjectView, s: APIServerState) -> Option<APIError> {
3217.     let key = ObjectRef {
3218.         kind: obj.kind,
3219.         namespace: namespace,
3220.         name: name,
3221.     };
3222.     if obj.metadata.name is None {
3223.         // Update fails because the name of the object is not provided
3224.         Some(APIError::BadRequest)
3225.     } else if name != obj.metadata.name->0 {
3226.         // Update fails because the name of the provided object
3227.         // does not match the name sent on the request
3228.         Some(APIError::BadRequest)
3229.     } else if obj.metadata.namespace is Some
3230.         && namespace != obj.metadata.namespace->0 {
3231.         // Update fails because the namespace of the provided object
3232.         // does not match the namespace sent on the request
3233.         Some(APIError::BadRequest)
3234.     } else if !unmarshallable_object(obj, installed_types) {
3235.         // Update fails because the provided object is not well formed
3236.         // TODO: should the error be BadRequest?
3237.         Some(APIError::BadRequest)
3238.     } else if !s.resources.contains_key(key) {
3239.         // Update fails because the object does not exist
3240.         // TODO: check AllowCreateOnUpdate() to see whether to support create-on-update
3241.         Some(APIError::ObjectNotFound)
3242.     } else if obj.metadata.resource_version is None
3243.         && !allow_unconditional_update(key.kind) {
3244.         // Update fails because the object does not provide a rv and unconditional update is not supported
3245.         Some(APIError::Invalid)
3246.     } else if obj.metadata.resource_version is Some
3247.         && obj.metadata.resource_version != s.resources[key].metadata.resource_version {
3248.         // Update fails because the object has a wrong rv
3249.         Some(APIError::Conflict)
3250.     } else if obj.metadata.uid is Some
3251.         && obj.metadata.uid != s.resources[key].metadata.uid {
3252.         // Update fails because the object has a wrong uid
3253.         Some(APIError::Conflict)
3254.     } else {
3255.         None
3256.     }
3257. }
