3267.             namespace: Some(req.namespace), // Overwrite namespace since it might not be provided
3268.             resource_version: old_obj.metadata.resource_version, // Overwrite rv since it might not be provided
3269.             uid: old_obj.metadata.uid, // Overwrite uid since it might not be provided
3270.             deletion_timestamp: old_obj.metadata.deletion_timestamp, // Ignore any change to deletion_timestamp
3271.             ..req.obj.metadata
3272.         },
