3283.         metadata_transition_validity_check(updated_obj, old_obj)
3284.     } else if object_validity_check(updated_obj, installed_types) is Some {
3285.         object_validity_check(updated_obj, installed_types)
3286.     } else if object_transition_validity_check(updated_obj, old_obj, installed_types) is Some {
