3293. #[verifier(inline)]
3294. pub open spec fn handle_update_request(installed_types: InstalledTypes, req: UpdateRequest, s: APIServerState) -> (APIServerState, UpdateResponse) {
3295.     if update_request_admission_check(installed_types, req, s) is Some {
3296.         // Update fails.
3297.         (s, UpdateResponse{res: Err(update_request_admission_check(installed_types, req, s)->0)})
3298.     } else {
3299.         let old_obj = s.resources[req.key()];
3300.         let updated_obj = updated_object(req, old_obj);
3301.         if updated_obj == old_obj {
3302.             // Update is a noop because there is nothing to update
3303.             // so the resource version counter does not increase here,
3304.             // and the resource version of this object remains the same.
3305.             (s, UpdateResponse{res: Ok(old_obj)})
3306.         } else {
3307.             // Update changes something in the object (either in spec or metadata), so we set it a newer resource version,
3308.             // which is the current rv counter.
3309.             let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3310.             if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3311.                 // Update fails.
3312.                 (s, UpdateResponse{res: Err(updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types)->0)})
3313.             } else {
3314.                 // Update succeeds.
3315.                 if updated_obj_with_new_rv.metadata.deletion_timestamp is None
3316.                     || (updated_obj_with_new_rv.metadata.finalizers is Some
3317.                         && updated_obj_with_new_rv.metadata.finalizers->0.len() > 0)
3318.                 {
3319.                     // The regular update case, where the object has no deletion timestamp set
3320.                     // or has at least one finalizer.
3321.                     (APIServerState {
3322.                         resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3323.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3324.                         ..s
3325.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3326.                 } else {
3327.                     // The delete-during-update case, where the update removes the finalizers from
3328.                     // the object that has a deletion timestamp, so the object needs to be deleted now.
3329.                     //
3330.                     // NOTE: in the actual implementation, when handling an update request,
3331.                     // the API server first applies the update to the object in the key-value store,
3332.                     // then checks whether the object can be deleted.
3333.                     // If so, it continues to delete the object from the key-value store before replying
3334.                     // to the update request.
3335.                     // This means that there is a super short window where the object has been updated in the store
3336.                     // (with a deletion timestamp and without any finalizer), but has not been deleted yet.
3337.                     // This behavior, strictly speaking, makes the entire Update operation not atomic.
3338.                     // We choose to still model the Update operation as an atomic step for simplicity.
3339.                     // This design choice does not affect the correctness of the controller that issues Update
3340.                     // in a blocking manner because the controller will never observe this intermediate state between
3341.                     // the update and deletion.
3342.                     // More generally speaking, this modeling won't affect the correctness of any controller that
3343.                     // treats a terminating object without finalizers as a non-existing object --- a good practice
3344.                     // controllers should follow.
3345.                     //
3346.                     // NOTE: the API server should also check whether the deletion grace period in the metadata
3347.                     // is set to 0 before deleting the object in case of graceful deletion
3348.                     // (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L533).
3349.                     // Here we omit that condition because graceful deletion is not supported.
3350.                     (APIServerState {
3351.                         resources: s.resources.remove(updated_obj_with_new_rv.object_ref()),
3352.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3353.                         ..s
3354.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3355.                 }
3356.             }
3357.         }
3358.     }
3359. }
