3491. pub open spec fn handle_get_then_update_request_msg(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3492.     recommends
3493.         msg.content.is_get_then_update_request(),
3494. {
3495.     let req = msg.content.get_get_then_update_request();
3496.     // Step 1: get the object
3497.     let get_req = GetRequest {
3498.         key: req.key()
3499.     };
3500.     let get_resp = handle_get_request(get_req, s);
3501.     match get_resp.res {
3502.         Ok(_) => {
3503.             let current_obj = s.resources[req.key()];
3504.             // Step 2: if the object exists, perform a check using a predicate on object
3505.             // The predicate: Is the current object owned by req.owner_ref?
3506.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3507.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3508.                 // Step 3: if the check passes, overwrite the object with the new one
3509.                 // Note that resource_version and uid comes from the current object to avoid conflict error
3510.                 let new_obj = DynamicObjectView {
3511.                     metadata: ObjectMetaView {
3512.                         resource_version: current_obj.metadata.resource_version,
3513.                         uid: current_obj.metadata.uid,
3514.                         ..req.obj.metadata
3515.                     },
3516.                     ..req.obj
3517.                 };
3518.                 let update_req = UpdateRequest {
3519.                     name: req.name,
3520.                     namespace: req.namespace,
3521.                     obj: new_obj,
3522.                 };
