1608.     pub open spec fn init(self) -> StatePred<ClusterState> {
1609.         |s: ClusterState| {
1610.             // The API server is initialized...
1611.             &&& (api_server(self.installed_types).init)(s.api_server)
1612.             // and the built-in controllers are initialized...
1613.             &&& (builtin_controllers().init)(())
1614.             // and the network is initialized...
1615.             &&& (network().init)(s.network)
1616.             // and message drop is enabled...
1617.             &&& s.req_drop_enabled
1618.             // and pod monkey is enabled...
1619.             &&& s.pod_monkey_enabled
1620.             // and for each controller...
1621.             &&& forall |key| #[trigger] self.controller_models.contains_key(key)
1622.                 ==> {
1623.                     let model = self.controller_models[key];
1624.                     // its internal state exists...
1625.                     &&& s.controller_and_externals.contains_key(key)
1626.                     // and is initialized...
1627.                     &&& (controller(model.reconcile_model, key).init)(s.controller_and_externals[key].controller)
1628.                     // and crash for this controller is enabled...
1629.                     &&& s.controller_and_externals[key].crash_enabled
1630.                     // and if the controller has an associated external system...
1631.                     &&& model.external_model is Some
1632.                         ==> {
1633.                             // the internal state of that external system exists...
1634.                             &&& s.controller_and_externals[key].external is Some
1635.                             // and is initialized.
1636.                             &&& (external(model.external_model->0).init)(s.controller_and_externals[key].external->0)
1637.                         }
1638.                 }
1639.         }
1640.     }
