1663.     pub open spec fn api_server_next(self) -> Action<ClusterState, Option<Message>, ()> {
1664.         let result = |input: Option<Message>, s: ClusterState| {
1665.             let host_result = self.api_server().next_result(
1666.                 APIServerActionInput{ recv: input },
1667.                 s.api_server
1668.             );
1669.             let msg_ops = MessageOps {
1670.                 recv: input,
1671.                 send: host_result.get_Enabled_1().send,
1672.             };
1673.             let network_result = network().next_result(msg_ops, s.network);
1674. 
1675.             (host_result, network_result)
1676.         };
1677.         Action {
1678.             precondition: |input: Option<Message>, s: ClusterState| {
1679.                 &&& received_msg_destined_for(input, HostId::APIServer)
1680.                 &&& result(input, s).0.is_Enabled()
1681.                 &&& result(input, s).1.is_Enabled()
1682.             },
1683.             transition: |input: Option<Message>, s: ClusterState| {
1684.                 let (host_result, network_result) = result(input, s);
1685.                 (ClusterState {
1686.                     api_server: host_result.get_Enabled_0(),
1687.                     network: network_result.get_Enabled_0(),
1688.                     ..s
1689.                 }, ())
1690.             },
1691.         }
1692.     }
