1696.             let host_result = self.builtin_controllers().next_result(
1697.                 BuiltinControllersActionInput {
1698.                     choice: input.0,
1699.                     key: input.1,
1700.                     rpc_id_allocator: s.rpc_id_allocator,
1701.                     resources: s.api_server.resources,
1702.                 },
1703.                 ()
1704.             );
1705.             let msg_ops = MessageOps {
1706.                 recv: None,
1707.                 send: host_result.get_Enabled_1().send,
1708.             };
1709.             let network_result = network().next_result(msg_ops, s.network);
1710. 
1711.             (host_result, network_result)
1712.         };
1713.         Action {
1714.             precondition: |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1715.                 &&& result(input, s).0.is_Enabled()
1716.                 &&& result(input, s).1.is_Enabled()
1717.             },
1718.             transition: |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1719.                 let (host_result, network_result) = result(input, s);
1720.                 (ClusterState {
1721.                     network: network_result.get_Enabled_0(),
1722.                     rpc_id_allocator: host_result.get_Enabled_1().rpc_id_allocator,
1723.                     ..s
1724.                 }, ())
