1746.             let host_result = self.controller(controller_id).next_result(
1747.                 ControllerActionInput{recv: input.0, scheduled_cr_key: input.1, rpc_id_allocator: s.rpc_id_allocator},
1748.                 s.controller_and_externals[controller_id].controller
1749.             );
