1758.         Action {
1759.             precondition: |input: (Option<Message>, Option<ObjectRef>), s: ClusterState| {
1760.                 &&& self.controller_models.contains_key(controller_id)
1761.                 &&& input.1 is Some
1762.                 &&& received_msg_destined_for(input.0, HostId::Controller(controller_id, input.1->0))
1763.                 &&& result(input, s).0.is_Enabled()
