3079. #[verifier(inline)]
3080. pub open spec fn handle_create_request(installed_types: InstalledTypes, req: CreateRequest, s: APIServerState) -> (APIServerState, CreateResponse) {
3081.     if create_request_admission_check(installed_types, req, s) is Some {
3082.         // Creation fails.
3083.         (s, CreateResponse{res: Err(create_request_admission_check(installed_types, req, s)->0)})
3084.     } else {
3085.         let created_obj = DynamicObjectView {
3086.             kind: req.obj.kind,
3087.             metadata: ObjectMetaView {
3088.                 // Set name for new object if name is not provided, here we generate
3089.                 // a unique name. The uniqueness is guaranteed by generated_name_is_unique.
3090.                 name: if req.obj.metadata.name is Some {
3091.                     req.obj.metadata.name
3092.                 } else {
3093.                     Some(generate_name(s))
3094.                 },
3095.                 namespace: Some(req.namespace), // Set namespace for new object
3096.                 resource_version: Some(s.resource_version_counter), // Set rv for new object
3097.                 uid: Some(s.uid_counter), // Set uid for new object
3098.                 deletion_timestamp: None, // Unset deletion timestamp for new object
3099.                 ..req.obj.metadata
3100.             },
3101.             spec: req.obj.spec,
3102.             status: marshalled_default_status(req.obj.kind, installed_types), // Overwrite the status with the default one
3103.         };
3104.         if s.resources.contains_key(created_obj.object_ref()) {
3105.             // Note 1: You might find this branch redundant since we already have
3106.             // generated_name_is_unique which guarantees that the created_obj's
3107.             // key is different from any existing keys even if name was not provided.
3108.             // But we still add this branch just to avoid calling generated_name_is_unique
3109.             // when we want to show that create without a provided name does not override
3110.             // an existing object when writing proofs.
3111.             //
3112.             // Note 2: Adding this branch also means that if we want to prove the object
3113.             // is eventually created by a create request without the name provided,
3114.             // we need to explicitly call generated_name_is_unique to show that
3115.             // we do not fall into this branch.
3116.             (s, CreateResponse{res: Err(APIError::ObjectAlreadyExists)})
3117.         } else if created_object_validity_check(created_obj, installed_types) is Some {
3118.             // Creation fails.
3119.             (s, CreateResponse{res: Err(created_object_validity_check(created_obj, installed_types)->0)})
3120.         } else {
3121.             // Creation succeeds.
3122.             (APIServerState {
3123.                 resources: s.resources.insert(created_obj.object_ref(), created_obj),
3124.                 uid_counter: s.uid_counter + 1,
3125.                 resource_version_counter: s.resource_version_counter + 1,
3126.                 ..s
3127.             }, CreateResponse{res: Ok(created_obj)})
3128.         }
3129.     }
3130. }
