3132. pub open spec fn delete_request_admission_check(req: DeleteRequest, s: APIServerState) -> Option<APIError> {
3133.     if !s.resources.contains_key(req.key) {
3134.         // Deletion fails because the object does not exist
3135.         Some(APIError::ObjectNotFound)
3136.     } else if req.preconditions is Some {
3137.         let preconditions = req.preconditions->0;
3138.         if preconditions.uid is Some && preconditions.uid != s.resources[req.key].metadata.uid {
3139.             // Deletion fails because the uid of the object does not match the uid in the precondition
3140.             Some(APIError::Conflict)
3141.         } else if preconditions.resource_version is Some && preconditions.resource_version != s.resources[req.key].metadata.resource_version {
3142.             // Deletion fails because the resource version of the object does not match the resource version in the precondition
3143.             Some(APIError::Conflict)
3144.         } else {
3145.             None
3146.         }
3147.     } else {
3148.         None
3149.     }
3150. }
