3491. pub open spec fn handle_get_then_update_request_msg(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3492.     recommends
3493.         msg.content.is_get_then_update_request(),
3494. {
3495.     let req = msg.content.get_get_then_update_request();
3496.     // Step 1: get the object
3497.     let get_req = GetRequest {
3498.         key: req.key()
3499.     };
3500.     let get_resp = handle_get_request(get_req, s);
3501.     match get_resp.res {
3502.         Ok(_) => {
3503.             let current_obj = s.resources[req.key()];
3504.             // Step 2: if the object exists, perform a check using a predicate on object
3505.             // The predicate: Is the current object owned by req.owner_ref?
