3648. pub open spec fn run_scheduled_reconcile(model: ReconcileModel) -> ControllerAction {
3649.     Action {
3650.         precondition: |input: ControllerActionInput, s: ControllerState| {
3651.             &&& input.scheduled_cr_key is Some
3652.             &&& input.scheduled_cr_key->0.kind == model.kind
3653.             &&& s.scheduled_reconciles.contains_key(input.scheduled_cr_key->0)
3654.             &&& input.recv is None
3655.             &&& !s.ongoing_reconciles.contains_key(input.scheduled_cr_key->0)
3656.         },
3657.         transition: |input: ControllerActionInput, s: ControllerState| {
3658.             let cr_key = input.scheduled_cr_key->0;
3659.             let (new_allocator, reconcile_id) = s.reconcile_id_allocator.allocate();
3660.             let initialized_ongoing_reconcile = OngoingReconcile {
3661.                 triggering_cr: s.scheduled_reconciles[cr_key],
3662.                 pending_req_msg: None,
3663.                 local_state: (model.init)(),
3664.                 reconcile_id: reconcile_id
3665.             };
3666.             let s_prime = ControllerState {
3667.                 ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, initialized_ongoing_reconcile),
3668.                 scheduled_reconciles: s.scheduled_reconciles.remove(cr_key),
3669.                 reconcile_id_allocator: new_allocator,
3670.                 ..s
3671.             };
3672.             let output = ControllerActionOutput {
3673.                 send: Multiset::empty(),
3674.                 rpc_id_allocator: input.rpc_id_allocator,
3675.             };
3676.             (s_prime, output)
3677.         },
3678.     }
3679. }
